a=p['original'];b=p['candidate']
def dif(a,b,path=''):
 if type(a)"'!=type(b): print(path);return
 if isinstance(a,dict):
  for k in dict.fromkeys([*a,*b]):
   if k not in a or k not in b: print(path+'"'/'+k)
   else: dif(a[k],b[k],path+'/'+k)
 elif isinstance(a,list):
  if a"'!=b: print(path)
 elif a!=b: print(path,'"':',str(a)[:60],'=>',str(b)[:60])
dif(a,b)
prep={x['id']:x for x in p['preparation']}
seen=set();missing=set()
def visit(i):
 if i in seen:return
 seen.add(i)
 if i not in prep:missing.add(i);return
 for j in prep[i]['requires']:visit(j)
for i in b['requires']:visit(i)
print('preparation closure',len(seen),'missing',missing,'not reached',set(prep)-seen)
print('max',sum(x['points'] for x in b['examData']['scoring']['steps']))
